","/* ── Stock Detail Page ─ Horizon Design Tokens ───────────────────────── */

/* Page layout */
.sd-container {
 max-width: 1200px;
 margin: 0 auto;
 padding: 32px 24px;
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 min-height: 100vh;
}

/* Shared section title */
.sd-section-title {
 margin: 0 0 16px;
 font-size: 20px;
 font-weight: 600;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
}

/* ── Stock Header ───────────────────────────────────────────────────── */
.sd-header {
 margin-bottom: 32px;
 padding-bottom: 20px;
 border-bottom: 1px solid rgb(var(--now-color_divider--tertiary, 220, 224, 226));
}
.sd-header-top {
 display: flex;
 align-items: center;
 gap: 16px;
 margin-bottom: 10px;
 flex-wrap: wrap;
}
.sd-header-number {
 margin: 0;
 font-size: 28px;
 font-weight: 600;
 color: rgb(var(--now-color--primary-2, 0, 128, 163));
}
.sd-status-badge {
 display: inline-block;
 padding: 4px 14px;
 border-radius: 12px;
 font-size: 13px;
 font-weight: 600;
 color: #fff;
}
.sd-badge-available { background: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.sd-badge-reserved { background: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.sd-badge-inspection { background: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.sd-badge-blocked { background: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.sd-badge-quarantined{ background: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.sd-badge-expired { background: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }

.sd-header-info {
 display: flex;
 align-items: center;
 gap: 8px;
 flex-wrap: wrap;
 font-size: 15px;
 color: rgb(var(--now-color_text--secondary, 73, 80, 84));
}
.sd-header-info-item { font-weight: 500; }
.sd-header-info-sep {
 color: rgb(var(--now-color_divider--tertiary, 220, 224, 226));
 user-select: none;
}

/* ── Quantity Cards ──────────────────────────────────────────────────── */
.sd-qty-grid {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 gap: 20px;
 margin-bottom: 40px;
}
.sd-qty-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: 28px 16px;
 border-radius: 8px;
 background: rgb(var(--now-color_background--secondary, 245, 246, 247));
 border: 1px solid rgb(var(--now-color_divider--tertiary, 220, 224, 226));
 transition: box-shadow 0.15s ease;
}
.sd-qty-card:hover { box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08); }
.sd-qty-value {
 font-size: 40px;
 font-weight: 700;
 line-height: 1.1;
 margin-bottom: 8px;
}
.sd-qty-label {
 font-size: 13px;
 font-weight: 500;
 color: rgb(var(--now-color_text--secondary, 73, 80, 84));
 text-align: center;
}
.sd-qty-total .sd-qty-value { color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.sd-qty-reserved .sd-qty-value { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.sd-qty-available .sd-qty-value{ color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }

/* ── Details Panel ──────────────────────────────────────────────────── */
.sd-details-section { margin-bottom: 40px; }
.sd-details-grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: 24px;
}
.sd-details-col { display: flex; flex-direction: column; gap: 14px; }
.sd-detail-item { display: flex; flex-direction: column; }
.sd-detail-label {
 font-size: 12px;
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.4px;
 color: rgb(var(--now-color_text--secondary, 73, 80, 84));
 margin-bottom: 3px;
}
.sd-detail-value {
 font-size: 15px;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
}

/* Batch Details sub-section */
.sd-batch-details {
 margin-top: 24px;
 padding-top: 20px;
 padding-left: 16px;
 border-left: 3px solid rgb(var(--now-color--primary-2, 0, 128, 163));
}
.sd-batch-title {
 margin: 0 0 16px;
 font-size: 16px;
 font-weight: 600;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
}

/* Quality status colors */
.sd-quality-passed { color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); font-weight: 600; }
.sd-quality-failed { color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); font-weight: 600; }
.sd-quality-pending { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); font-weight: 600; }
.sd-quality-conditional { color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); font-weight: 600; }

/* ── Action Bar ─────────────────────────────────────────────────────── */
.sd-action-section { margin-bottom: 40px; }
.sd-action-bar {
 display: flex;
 flex-wrap: wrap;
 gap: 12px;
}

/* ── Related Tables (shared) ────────────────────────────────────────── */
.sd-related-section { margin-bottom: 40px; }
.sd-table-wrap {
 border: 1px solid rgb(var(--now-color_divider--tertiary, 220, 224, 226));
 border-radius: 8px;
 overflow-x: auto;
}
.sd-table {
 display: grid;
 grid-template-columns: 1fr;
 width: 100%;
}
.sd-table-row {
 display: grid;
 gap: 12px;
 padding: 12px 16px;
 align-items: center;
 border-bottom: 1px solid rgb(var(--now-color_divider--tertiary, 220, 224, 226));
 font-size: 14px;
}
.sd-table-row:last-child { border-bottom: none; }
.sd-table-header {
 background: rgb(var(--now-color_background--secondary, 245, 246, 247));
 font-weight: 600;
 font-size: 12px;
 text-transform: uppercase;
 letter-spacing: 0.4px;
 color: rgb(var(--now-color_text--secondary, 73, 80, 84));
}
.sd-table-row:not(.sd-table-header):hover {
 background: rgb(var(--now-color_background--secondary, 245, 246, 247));
}
.sd-table-cell {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
}
.sd-msg-cell {
 white-space: normal;
 word-break: break-word;
}
.sd-link-cell a {
 font-weight: 600;
 color: rgb(var(--now-color--primary-2, 0, 128, 163));
 text-decoration: none;
}
.sd-link-cell a:hover { text-decoration: underline; }
.sd-qty-cell { font-weight: 600; font-variant-numeric: tabular-nums; }

/* Table column layouts */
.sd-txn-table .sd-table-row { grid-template-columns: 1.2fr 1.2fr 0.8fr 1.2fr 0.9fr; min-width: 550px; }
.sd-req-table .sd-table-row { grid-template-columns: 1fr 1.2fr 0.8fr 0.8fr 0.9fr 1fr; min-width: 650px; }
.sd-alert-table .sd-table-row { grid-template-columns: 1fr 1fr 0.8fr 2fr 0.9fr 1fr; min-width: 750px; }

/* ── Status / Priority / Severity Colors ────────────────────────────── */
.sd-st-completed { color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); font-weight: 600; }
.sd-st-approved { color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); font-weight: 600; }
.sd-st-pending { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); font-weight: 600; }
.sd-st-cancelled { color: rgb(var(--now-color_text--tertiary, 109, 117, 121)); font-weight: 600; }
.sd-st-rejected { color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); font-weight: 600; }

.sd-prio-critical { color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); font-weight: 600; }
.sd-prio-high { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); font-weight: 600; }
.sd-prio-medium { color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); font-weight: 600; }
.sd-prio-low { color: rgb(var(--now-color_text--tertiary, 109, 117, 121)); font-weight: 600; }

/* ── Empty state ────────────────────────────────────────────────────── */
.sd-empty {
 padding: 32px 16px;
 text-align: center;
 color: rgb(var(--now-color_text--secondary, 73, 80, 84));
 font-size: 14px;
}

/* ── Loading / Error ────────────────────────────────────────────────── */
.sd-loading, .sd-error {
 display: flex;
 align-items: center;
 justify-content: center;
 min-height: 300px;
 font-size: 16px;
}
.sd-loading { color: rgb(var(--now-color_text--secondary, 73, 80, 84)); }
.sd-error { color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }

/* ── Responsive ─────────────────────────────────────────────────────── */
@media (max-width: 900px) {
 .sd-qty-grid { grid-template-columns: 1fr; }
 .sd-details-grid { grid-template-columns: 1fr; }
 .sd-action-bar { flex-direction: column; }
}
@media (max-width: 600px) {
 .sd-header-top { flex-direction: column; align-items: flex-start; gap: 8px; }
 .sd-table-row { font-size: 13px; gap: 6px; padding: 10px 12px; }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React from "react";
