","import React, { useState, useEffect } from "react";
import StockHeader from "./components/StockHeader";
import QuantityCards from "./components/QuantityCards";
import DetailsPanel from "./components/DetailsPanel";
import ActionBar from "./components/ActionBar";
import RelatedTransactions from "./components/RelatedTransactions";
import RelatedRequests from "./components/RelatedRequests";
import RelatedAlerts from "./components/RelatedAlerts";
import "./app.css";

interface StockRecord {
 number: string;
 material: string;
 materialSysId: string;
 inventoryType: string;
 status: string;
 location: string;
 locationSysId: string;
 batchLot: string;
 batchLotSysId: string;
 totalQty: string;
 reservedQty: string;
 availableQty: string;
 safetyStock: string;
 reorderLevel: string;
 lastUpdated: string;
 expiryDate: string;
 active: string;
 sysId: string;
}

interface BatchInfo {
 batchNumber: string;
 qualityStatus: string;
 manufacturingDate: string;
 expiryDate: string;
 supplierBatchNumber: string;
 certificateNumber: string;
}

interface Transaction {
 number: string;
 transactionType: string;
 quantity: string;
 transactionDate: string;
 status: string;
 sysId: string;
}

interface RequestRecord {
 number: string;
 requestType: string;
 quantityRequested: string;
 priority: string;
 status: string;
 requestedDate: string;
 sysId: string;
}

interface Alert {
 number: string;
 alertType: string;
 severity: string;
 alertMessage: string;
 status: string;
 alertDate: string;
 sysId: string;
}

interface StockDetailData {
 stock: StockRecord;
 batch: BatchInfo | null;
 transactions: Transaction[];
 requests: RequestRecord[];
 alerts: Alert[];
}

const API_BASE = "/api/x_2056099_indust_0/stock_detail_api/record";

export default function App() {
 const [data, setData] = useState<StockDetailData | null>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");

 useEffect(() => {
 const params = new URLSearchParams(window.location.search);
 const sysId = params.get("sys_id") || "";

 if (!sysId) {
 setError("No sys_id parameter provided. Please navigate from the Inventory Overview page.");
 setLoading(false);
 return;
 }

 fetch(`${API_BASE}?sys_id=${encodeURIComponent(sysId)}`, {
 headers: {
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck,
 },
 })
 .then((r) => {
 if (!r.ok) throw new Error(`HTTP ${r.status}`);
 return r.json();
 })
 .then((d) => {
 if (d.error) throw new Error(d.error);
 setData(d.result);
 })
 .catch((e) => setError(e.message))
 .finally(() => setLoading(false));
 }, []);

 if (loading) return <div className="sd-loading">Loading stock details…</div>;
 if (error) return <div className="sd-error">Error: {error}</div>;
 if (!data || !data.stock) return <div className="sd-error">No stock data available.</div>;

 return (
 <div className="sd-container">
 <StockHeader stock={data.stock} />
 <QuantityCards stock={data.stock} />
 <DetailsPanel stock={data.stock} batch={data.batch} />
 <ActionBar stock={data.stock} />
 <RelatedTransactions transactions={data.transactions} />
 <RelatedRequests requests={data.requests} />
 <RelatedAlerts alerts={data.alerts} />
 </div>
